const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    full_name: body.full_name || body.name || 'Anonymous Lead',
    email: body.email || '',
    phone: (body.phone || body.telephone || '').replace(/[^0-9+]/g, ''),
    company: body.company || body.organization || '',
    message: body.message || body.notes || body.project_details || '',
    budget_input: body.budget || '',
    timeline_input: body.timeline || '',
    source: body.source || 'website_form',
    raw_payload: body
  }
}];

const response = $input.first().json;
const leadInput = $('Normalize Inbound Payload').first().json;
let parsed = {};
try {
  const rawText = response.content?.[0]?.text || '{}';
  parsed = JSON.parse(rawText.replace(/```json\n?|```/g, '').trim());
} catch (e) {
  parsed = {
    score: 50,
    tier: 'warm',
    need_summary: 'Needs manual review',
    budget_range: 'no signal',
    timeline: 'no signal',
    authority: 'no signal',
    disqualify: false,
    reply_draft: 'Thank you for reaching out to Sigma Tactix. We received your request and will follow up shortly.',
    internal_note: 'Parse fallback triggered'
  };
}

const nextFollowup = parsed.tier === 'hot' ? new Date(Date.now() + 1 * 86400000).toISOString() : new Date(Date.now() + 2 * 86400000).toISOString();

return [{
  json: {
    ...leadInput,
    score: parsed.score,
    tier: parsed.tier,
    need_summary: parsed.need_summary,
    budget_range: parsed.budget_range,
    timeline: parsed.timeline,
    authority: parsed.authority,
    disqualified: !!parsed.disqualify,
    reply_draft: parsed.reply_draft,
    internal_note: parsed.internal_note,
    status: parsed.disqualify ? 'disqualified' : (parsed.tier === 'hot' ? 'qualified' : 'qualifying'),
    next_followup_at: nextFollowup,
    last_contact_at: new Date().toISOString()
  }
}];
